#' Print an \code{irock} Object
#'
#' @description
#' Print an object generated by \code{irock}.
#'
#' @param x a fitted object returned by \code{\link{irock}}.
#' @param ... additional arguments passed to \code{print()} for the
#'   coefficient vector.
#'
#' @return
#' Invisibly returns \code{x}.
#'
#' @seealso
#' \code{\link{irock}}, \code{\link{summary.irock}}
#'
#' @export
print.irock <- function(x, ...) {
  if (!is.null(x$call)) {
    cat("Call:\n")
    dput(x$call)
  }
  cat("\nExpected shortfall regression coefficients:\n")
  print(x$coefficients, ...)
  if (!is.null(x$na.action)) {
    cat("  (", stats::naprint(x$na.action), ")\n", sep = "")
  }
  invisible(x)
}
